const io=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){e.target.style.opacity='1';e.target.style.transform='translateY(0)';io.unobserve(e.target)}})},{threshold:.1});
document.querySelectorAll('.pkg,.kt-list li,.plans article').forEach((el,i)=>{el.style.opacity='0';el.style.transform='translateY(20px)';el.style.transition=`opacity .6s ease ${i*40}ms,transform .6s ease ${i*40}ms`;io.observe(el)});
